using ET;
using ET.Server;
using FirepowerLoop.Arcade;
if(args.Length!=3||!args.Contains("testClass=OutsideRoutes")||!args.Contains("maxTests=10")||!args.Contains("includePassingTests=true"))throw new ArgumentException("OutsideRoutes maxTests=10 includePassingTests=true required");
World.Instance.AddSingleton(ServerConfig.CreateForValidation("OnlineLocal",n=>File.ReadAllBytes(Path.Combine("Server/GameServer/Config/Luban",n+".bytes"))));
ArcadeRoundLayoutParameters Layout(int n)=>ArcadeRoundLayoutParameters.FromConfig(ServerConfig.Instance.Tables.TbArcadeRoundLayout.Get($"arena.{n}.round.1"));
var tests=new (string,Action)[]{
("FarmFourDirections",()=>{var p=Layout(22);foreach(int i in Enumerable.Range(0,4)){Check(ArcadeOutsideRouteRules.TryStart(p,i,30.5f,30.5f,.95f,out var s));Check(Math.Abs(s.StartX)>30.5f||Math.Abs(s.StartZ)>30.5f);Check(s.TargetX==p.Entries[i].X&&s.TargetZ==p.Entries[i].Y);}}),
("AllOrdinaryLayouts",()=>{foreach(var row in ServerConfig.Instance.Tables.TbArcadeRoundLayout.DataList){var p=ArcadeRoundLayoutParameters.FromConfig(row);if(p.ArenaConfigNumber==1||p.ArenaConfigNumber==21)continue;var stage=ServerConfig.Instance.EarlyStages.GetValueOrDefault(p.ArenaConfigNumber);foreach(int i in Enumerable.Range(0,p.Entries.Count))Check(ArcadeOutsideRouteRules.TryStart(p,i,stage?.HalfWidth??19.5f,stage?.HalfHeight??19.5f,.95f,out _));}}),
("SpecialMapsPreserved",()=>{Check(!ArcadeOutsideRouteRules.TryStart(Layout(1),0,19.5f,19.5f,.95f,out _));Check(!ArcadeOutsideRouteRules.TryStart(Layout(21),0,20.5f,19.5f,.95f,out _));}),
("OnlyVerifiedMouthCaps",()=>{foreach(int n in new[]{23,24,25}){var p=Layout(n);Check(p.Obstacles.Any(o=>ArcadeOutsideRouteRules.IsPlayerMouthCap(p,o)));Check(p.Obstacles.Where(o=>o.BlocksProjectiles).All(o=>!ArcadeOutsideRouteRules.IsPlayerMouthCap(p,o)));}Check(Layout(22).Obstacles.All(o=>!ArcadeOutsideRouteRules.IsPlayerMouthCap(Layout(22),o)));}),
("InvalidIndicesRejected",()=>{Check(!ArcadeOutsideRouteRules.TryStart(Layout(22),-1,30.5f,30.5f,.95f,out _));Check(!ArcadeOutsideRouteRules.TryStart(Layout(22),4,30.5f,30.5f,.95f,out _));}),
("FallbackFindsOpenSide",()=>{foreach(var arena in ServerConfig.Instance.Tables.TbArcadeArena.DataList){var p=Layout(arena.ArenaNumber);var stage=ServerConfig.Instance.EarlyStages.GetValueOrDefault(arena.ArenaNumber);Check(ArcadeOutsideRouteRules.TryStartFallback(p,0,20,stage?.HalfWidth??19.5f,stage?.HalfHeight??19.5f,.95f,arena.Obstacles.Select(o=>new ArcadeLayoutObstacle(o.CenterX,o.CenterY,o.HalfWidth,o.HalfHeight)).ToArray(),out _));}Check(ArcadeOutsideRouteRules.TryStartFallback(Layout(22),0,30,30.5f,30.5f,.95f,new[]{new ArcadeLayoutObstacle(0,30,31,2)},out var s));Check(s.StartZ<30);}),
("FallbackClosedArenaRejected",()=>{var walls=new[]{new ArcadeLayoutObstacle(0,29,31,1),new ArcadeLayoutObstacle(0,-29,31,1),new ArcadeLayoutObstacle(29,0,1,31),new ArcadeLayoutObstacle(-29,0,1,31)};Check(!ArcadeOutsideRouteRules.TryStartFallback(Layout(22),0,30,30.5f,30.5f,.95f,walls,out _));}),
("SpecialArrivalNotCarrierIdentity",()=>{Check(!ArcadeOutsideRouteRules.HasSpecialArrival(1,0,false,false,false));Check(ArcadeOutsideRouteRules.HasSpecialArrival(18,1,false,false,false));Check(ArcadeOutsideRouteRules.HasSpecialArrival(13,0,false,false,false));Check(ArcadeOutsideRouteRules.HasSpecialArrival(0,0,true,false,false));}),
("ServerInitializesAndFreezes",()=>{var b=new OnlineArcadeBattleRuntime{ArenaConfigNumber=22,RoundLayout=Layout(22)};var e=new OnlineArcadeEnemyRuntime{MoveSpeed=2,CurrentHealth=10};Call("InitializeOutsideEntry",b,e,0);Check(e.OutsideEntry.Active&&e.PositionX< -30.5f&&e.CanBeAttacked);float x=e.PositionX;Check((bool)Call("TickOutsideEntry",b,e,0));Check(e.PositionX==x);Check((bool)Call("TickOutsideEntry",b,e,1));Check(e.PositionX>x&&e.PositionX<e.OutsideEntry.TargetX);e.ContentStunUntil=100;float held=e.PositionX;Call("TickOutsideEntry",b,e,1);Check(e.PositionX==held);var special=new OnlineArcadeEnemyRuntime{SpecialKind=1};Call("InitializeOutsideEntry",b,special,0);Check(special.OutsideEntry.Active);special=new OnlineArcadeEnemyRuntime{StageEnemy=new ArcadeStageEnemyState{Phase=1}};Call("InitializeOutsideEntry",b,special,0);Check(!special.OutsideEntry.Active);b.RoundLayout=Layout(21);b.ArenaConfigNumber=21;b.RoundBossEncounter=true;special=new OnlineArcadeEnemyRuntime();Call("InitializeOutsideEntry",b,special,0);Check(special.DockSeaEntry.Started&&!special.OutsideEntry.Active);special=new OnlineArcadeEnemyRuntime{ContentBossKind=1};Call("InitializeOutsideEntry",b,special,0);Check(!special.DockSeaEntry.Started&&!special.OutsideEntry.Active);}),
("SolidWallSweepRejected",()=>{Check(ArcadeOutsideRouteRules.Intersects(0,10,0,0,new ArcadeLayoutObstacle(0,5,2,1),.95f));Check(!ArcadeOutsideRouteRules.Intersects(5,10,5,0,new ArcadeLayoutObstacle(0,5,2,1),.95f));})};
int fails=0;foreach(var t in tests){try{t.Item2();Console.WriteLine("PASS OutsideRoutes."+t.Item1);}catch(Exception e){fails++;Console.WriteLine("FAIL OutsideRoutes."+t.Item1+": "+e.Message);}}return fails==0?0:1;
static void Check(bool yes){if(!yes)throw new Exception("Assertion failed");}

static object Call(string name,params object[] args)=>typeof(OnlineArcadeRunActorSystem).GetMethod(name,System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,args)!;
